"""Scenario YAML loading and parsing for the eval suite."""

from __future__ import annotations

from importlib.resources import files
from pathlib import Path
from typing import Any, Callable, Dict, List, Optional, cast

from pydantic import BaseModel, Field
from pydantic import ValidationError as PydanticValidationError

from rasa.shared.constants import ASSERTIONS_SCHEMA_EXTENSIONS_FILE
from rasa.shared.exceptions import RasaException
from rasa.shared.utils.yaml import (
    YamlValidationException,
    parse_raw_yaml,
    read_schema_file,
    validate_yaml_content_using_schema,
)

_SCENARIO_KEY = "scenario"
_SCENARIO_SCHEMA = "builder/copilot/mcp_server/schema/scenario_schema.yml"
_SLOT_ASSERTION_KEYS = frozenset({"slot_was_set", "slot_was_not_set"})

# Maps Rasa slot type names to a predicate that returns True for compatible values.
# `any` and unknown types are not checked. None is always valid (slot stays unset).
_SLOT_TYPE_VALIDATORS: Dict[str, Callable[[Any], bool]] = {
    "text": lambda v: isinstance(v, str),
    "bool": lambda v: isinstance(v, bool),
    "float": lambda v: isinstance(v, (int, float)) and not isinstance(v, bool),
    "categorical": lambda v: isinstance(v, str),
    "strict_categorical": lambda v: isinstance(v, str),
    "list": lambda v: isinstance(v, list),
}


class EvalScenarioError(RasaException):
    """Raised when a scenario YAML is missing or incorrectly formatted."""


class ScenarioSetup(BaseModel):
    """Initial state to inject before the simulation starts."""

    initial_slots: Dict[str, Any] = Field(default_factory=dict)


class ScenarioGoals(BaseModel):
    """Deterministic assertions and LLM-evaluated criteria for a scenario."""

    assertions: List[Dict[str, Any]] = Field(default_factory=list)
    criteria: List[str] = Field(default_factory=list)


class Scenario(BaseModel):
    """Parsed and validated representation of a scenario YAML."""

    name: str
    simulation_context: str
    setup: ScenarioSetup = Field(default_factory=ScenarioSetup)
    goals: ScenarioGoals = Field(default_factory=ScenarioGoals)
    slug: str = ""


def _validate_scenario_yaml(raw: Any, path: Path) -> None:
    """Run pykwalify schema validation on the raw parsed scenario YAML."""
    schema = cast(Dict[str, Any], read_schema_file(_SCENARIO_SCHEMA))
    extensions = [str(files("rasa").joinpath(ASSERTIONS_SCHEMA_EXTENSIONS_FILE))]
    try:
        validate_yaml_content_using_schema(raw, schema, schema_extensions=extensions)
    except YamlValidationException as exc:
        raise EvalScenarioError(f"Invalid scenario in '{path}':\n{exc}") from exc


def load_scenario(path: Path) -> Scenario:
    """Load and validate a scenario YAML file.

    Args:
        path: Absolute path to the scenario YAML file.

    Returns:
        Validated Scenario.

    Raises:
        EvalScenarioError: If the file is missing, unparseable, or has
            missing or invalid fields.
    """
    if not path.is_file():
        raise EvalScenarioError(f"Scenario file not found: '{path}'.")

    try:
        raw: Any = parse_raw_yaml(path.read_text(encoding="utf-8"))
    except Exception as exc:
        raise EvalScenarioError(f"Could not parse '{path}': {exc}") from exc

    _validate_scenario_yaml(raw, path)

    try:
        scenario = Scenario.model_validate(raw[_SCENARIO_KEY])
        return scenario.model_copy(update={"slug": path.stem})
    except PydanticValidationError as exc:
        raise EvalScenarioError(f"Invalid scenario in '{path}':\n{exc}") from exc


def _slot_names_from_refs(slot_refs: List[Any]) -> List[str]:
    return [ref["name"] for ref in slot_refs if isinstance(ref, dict) and "name" in ref]


def _slot_names_from_sequencing(steps: List[Any]) -> List[str]:
    return [
        step["slot_was_set"]
        for step in steps
        if isinstance(step, dict)
        and "slot_was_set" in step
        and isinstance(step["slot_was_set"], str)
    ]


def get_assertion_slot_names(assertions: List[Dict[str, Any]]) -> List[str]:
    """Return unique slot names from slot_was_set/slot_was_not_set assertions.

    Covers both top-level assertions (value is a list of {name: ...} dicts) and
    slot references inside sequencing steps (value is a plain slot-name string).
    """
    slot_names: List[str] = []
    for assertion_dict in assertions:
        # Schema enforces single-key assertion dicts; first key is the only key.
        key = next(iter(assertion_dict), None)
        if key in _SLOT_ASSERTION_KEYS:
            slot_names.extend(_slot_names_from_refs(assertion_dict[key] or []))
        elif key == "sequencing":
            slot_names.extend(_slot_names_from_sequencing(assertion_dict[key] or []))
    return list(dict.fromkeys(slot_names))


def get_assertion_slot_values(assertions: List[Dict[str, Any]]) -> Dict[str, Any]:
    """Return slot name → asserted value for slot assertions that specify a value."""
    values: Dict[str, Any] = {}
    for assertion_dict in assertions:
        key = next(iter(assertion_dict), None)
        if key in _SLOT_ASSERTION_KEYS:
            for slot_ref in assertion_dict[key] or []:
                if (
                    isinstance(slot_ref, dict)
                    and "name" in slot_ref
                    and "value" in slot_ref
                ):
                    values[slot_ref["name"]] = slot_ref["value"]
    return values


def check_slot_type_compatibility(
    slot_name: str, value: Any, slot_type: str
) -> Optional[str]:
    """Return an error message if value is incompatible with slot_type, else None.

    None values are always valid (slot stays unset). Unknown slot types are skipped.
    """
    if value is None:
        return None
    validator = _SLOT_TYPE_VALIDATORS.get(slot_type)
    if validator is None:
        return None
    if not validator(value):
        return (
            f"Slot '{slot_name}' has type '{slot_type}' but "
            f"initial value {value!r} is incompatible."
        )
    return None
